using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Globalization;using System.Diagnostics;using System.Threading.Tasks;using System.Windows.Forms;using ScreenRecorderLib;
namespace PCRecord {
 internal static class ExtendedVerification {
  public static int Run(Paths p){int exit=1;var rows=new List<object>();var metrics=new List<object>();bool reportFinished=false,closing=false,aborted=false;bool micOnly=Environment.GetEnvironmentVariable("PCRECORD_MIC_ONLY")=="1";string resultName=micOnly?"microphone-result.json":"extended-result.json";string folder=Path.Combine(p.Root,"verification");Directory.CreateDirectory(folder);
   using(var form=new TestPattern()){form.Text="PC Record — испытания устройств";var media=new MediaTools(p);var engine=new CaptureEngine(p,media,a=>{if(form.IsHandleCreated&&!form.IsDisposed)form.BeginInvoke(a);});
    string metricFile=Path.Combine(folder,"metrics-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6)+".jsonl");
    Action save=()=>Data.Write(Path.Combine(folder,resultName),Data.Map("running",true,"cases",rows,"metrics",metrics,"metricsFile",Path.GetFileName(metricFile),"note","Local private device recordings; no upload"));
    Action<int> finish=code=>{if(reportFinished)return;reportFinished=true;exit=code;Data.Write(Path.Combine(folder,resultName),Data.Map("running",false,"cases",rows,"metrics",metrics,"metricsFile",Path.GetFileName(metricFile),"exitCode",exit));engine.Dispose();};
    form.FormClosing+=async(s,e)=>{if(reportFinished)return;aborted=true;if(engine.Busy){e.Cancel=true;if(closing)return;closing=true;try{await Deadline(engine.Stop(),20);}catch(Exception ex){rows.Add(Failure("close-stop",ex));}rows.Add(Data.Map("test","verification-close","status","interrupted","reason","Window closed before verification completed"));finish(2);form.Close();}else{rows.Add(Data.Map("test","verification-close","status","interrupted"));finish(2);}};

    form.Shown+=async(s,e)=>{try{await Task.Delay(1000);var config=Data.Map("kind","window","source",form.Handle.ToInt64().ToString(CultureInfo.InvariantCulture),"format","MP4","fps",30,"resolution","source","systemAudio",false,"microphone",false,"camera",false);
     if(Environment.GetEnvironmentVariable("PCRECORD_LONG_ONLY")=="1")goto LongOnly;
     if(Environment.GetEnvironmentVariable("PCRECORD_TOOLBAR_ONLY")=="1")goto ToolbarOnly;
     if(micOnly)goto MicrophoneOnly;
     var loop=Recorder.GetSystemAudioLoopbackDevices().FirstOrDefault(d=>d.IsDefaultDevice)??Recorder.GetSystemAudioLoopbackDevices().FirstOrDefault();
     if(loop==null){rows.Add(Data.Map("test","system-audio","status","unavailable"));save();}else{try{var c=new Dictionary<string,object>(config);c["systemAudio"]=true;c["loopback"]=loop.DeviceName;c["systemVolume"]=100;using(var wav=Tone())using(var player=new System.Media.SoundPlayer(wav)){player.Load();var task=engine.Start(c,false);try{await Task.Delay(900);player.PlayLooping();await Task.Delay(6000);}finally{player.Stop();}var result=await engine.Stop();await task;var stats=await AudioStats(p,media,Data.Text(result,"path"));rows.Add(Data.Map("test","system-audio","status",Convert.ToDouble(stats["rms"])>.001?"pass":"no-signal","file",Data.Text(result,"path"),"measurement",stats));}}catch(Exception ex){rows.Add(Failure("system-audio",ex));}save();}
     MicrophoneOnly: if(Environment.GetEnvironmentVariable("PCRECORD_SKIP_MIC")=="1"){rows.Add(Data.Map("test","microphone-speech","status","skipped-by-owner","microphoneOpened",false));goto CameraOnly;}
     var mic=Recorder.GetSystemAudioCaptureDevices().FirstOrDefault(d=>d.IsDefaultDevice)??Recorder.GetSystemAudioCaptureDevices().FirstOrDefault();
     if(mic==null)rows.Add(Data.Map("test","microphone","status","unavailable"));else{try{var c=new Dictionary<string,object>(config);c["microphone"]=true;c["micDevice"]=mic.DeviceName;c["micVolume"]=100;if(micOnly)form.Text="PC Record — ГОВОРИТЕ: проверка микрофона 15 секунд";var task=engine.Start(c,false);await Task.Delay(micOnly?15000:7000);var result=await engine.Stop();await task;var stats=await AudioStats(p,media,Data.Text(result,"path"));rows.Add(Data.Map("test","microphone","status",Convert.ToDouble(stats["rms"])>.00005?"pass":"no-signal","file",Data.Text(result,"path"),"measurement",stats,"speechQualityTested",false));}catch(Exception ex){rows.Add(Failure("microphone",ex));}}save();
     if(micOnly){exit=rows.OfType<Dictionary<string,object>>().Any(d=>Data.Text(d,"status")=="pass")?0:2;return;}
     CameraOnly: var cam=Recorder.GetSystemVideoCaptureDevices().FirstOrDefault();
     if(cam==null)rows.Add(Data.Map("test","camera","status","unavailable"));else{foreach(bool overlay in new[]{false,true}){string name=overlay?"camera-overlay":"camera-alone";try{var c=new Dictionary<string,object>(config);if(overlay){c["camera"]=true;c["cameraDevice"]=cam.DeviceName;}else{c["kind"]="camera";c["source"]=cam.DeviceName;}var task=engine.Start(c,false);await Task.Delay(7000);var result=await engine.Stop();await task;string file=Data.Text(result,"path");var info=await media.Probe(file);await media.Stream("ffmpeg.exe","-v error -xerror -i pipe:0 -f null -",file,null,45);rows.Add(Data.Map("test",name,"status","pass","file",file,"metadata",info,"visualContentReviewed",false));}catch(Exception ex){rows.Add(Failure(name,ex));}save();}}
     if(Environment.GetEnvironmentVariable("PCRECORD_DEVICES_ONLY")=="1"){exit=rows.OfType<Dictionary<string,object>>().Any(d=>Data.Text(d,"status")=="failed")?1:0;return;}
     ToolbarOnly: try{var task=engine.Start(config,false);await Task.Delay(1500);using(var bar=new RecordingToolbar(engine,()=>form.Activate())){bar.Show();bar.RefreshStatus();bool visible=bar.Visible&&bar.TopMost;bar.TogglePause();if(Data.Text(engine.Status(),"state")!="Paused")throw new IOException("Панель не поставила запись на паузу");bar.TogglePause();bar.RefreshStatus();string shot=Path.Combine(folder,"floating-toolbar.png");using(var bitmap=new Bitmap(bar.Width,bar.Height)){bar.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(shot,System.Drawing.Imaging.ImageFormat.Png);}await bar.StopRecording();await task;if(!visible||engine.Busy)throw new IOException("Панель не остановила запись");rows.Add(Data.Map("test","floating-toolbar-pause-resume-stop","status","pass","visibleTopmost",visible,"excludeApiAccepted",bar.ExcludedFromCapture,"screenshot",shot));}}catch(Exception ex){rows.Add(Failure("floating-toolbar",ex));}save();
     if(Environment.GetEnvironmentVariable("PCRECORD_LONG_ONLY")=="1")goto LongOnly;
     if(Environment.GetEnvironmentVariable("PCRECORD_TOOLBAR_ONLY")=="1"){exit=0;return;}
     LongOnly: try{int durationSeconds=300;int.TryParse(Environment.GetEnvironmentVariable("PCRECORD_LONG_SECONDS")??"300",out durationSeconds);if(durationSeconds<60||durationSeconds>14400)throw new IOException("Неверная длительность теста");form.Text="PC Record — длительный тест "+durationSeconds+" секунд";metrics.Clear();var sw=Stopwatch.StartNew();var task=engine.Start(config,false);for(int i=0;!aborted&&sw.Elapsed.TotalSeconds<durationSeconds;i++){await Task.Delay(Math.Min(5000,Math.Max(1,(int)((durationSeconds-sw.Elapsed.TotalSeconds)*1000))));if(task.IsCompleted){await task;throw new IOException("Запись завершена до окончания проверки. "+Data.Text(engine.Status(),"warning"));}using(var proc=Process.GetCurrentProcess()){proc.Refresh();var measurement=Data.Map("seconds",sw.Elapsed.TotalSeconds,"workingSet",proc.WorkingSet64,"privateBytes",proc.PrivateMemorySize64);metrics.Add(measurement);File.AppendAllText(metricFile,Data.Json.Serialize(measurement)+Environment.NewLine,new System.Text.UTF8Encoding(false));}if(i%6==0){rows.Add(Data.Map("test","long-progress","status","running","seconds",sw.Elapsed.TotalSeconds));save();}}if(aborted){exit=2;return;}var result=await engine.Stop();await task;string file=Data.Text(result,"path");var info=await media.Probe(file);double duration=Double.Parse(Convert.ToString(((Dictionary<string,object>)info["format"])["duration"],CultureInfo.InvariantCulture),CultureInfo.InvariantCulture);if(duration<durationSeconds-15||duration>durationSeconds+45)throw new IOException("Неожиданная длительность: "+duration);await media.Stream("ffmpeg.exe","-v error -xerror -i pipe:0 -f null -",file,null,900);rows.Add(Data.Map("test","recording-profile-"+durationSeconds+"-seconds","status","pass","file",file,"duration",duration,"metrics",metrics,"metadata",info));}catch(Exception ex){rows.Add(Failure("long-recording",ex));}
     exit=rows.OfType<Dictionary<string,object>>().Any(d=>Data.Text(d,"status")=="failed")?1:0;
    }catch(Exception ex){rows.Add(Failure("test-harness",ex));}finally{finish(exit);form.Close();}};Application.Run(form);
   }return exit;
  }
  static async Task<T> Deadline<T>(Task<T> task,int seconds){if(await Task.WhenAny(task,Task.Delay(seconds*1000))!=task)throw new IOException("Истекло ожидание завершения записи");return await task;}
  static object Failure(string name,Exception ex){return Data.Map("test",name,"status","failed","error",ex.ToString());}
  static MemoryStream Tone(){var stream=new MemoryStream();var w=new BinaryWriter(stream);int rate=44100,count=rate*2;w.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));w.Write(36+count*2);w.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(rate);w.Write(rate*2);w.Write((short)2);w.Write((short)16);w.Write(System.Text.Encoding.ASCII.GetBytes("data"));w.Write(count*2);for(int i=0;i<count;i++)w.Write((short)(1200*Math.Sin(2*Math.PI*440*i/rate)));w.Flush();stream.Position=0;return stream;}
  static async Task<Dictionary<string,object>> AudioStats(Paths p,MediaTools m,string file){string pcm=Path.Combine(p.Temp,"audio-test-"+Guid.NewGuid().ToString("N")+".pcm");await m.Stream("ffmpeg.exe","-v error -i pipe:0 -vn -ac 1 -ar 16000 -f s16le pipe:1",file,pcm,45);byte[] bytes=await OwnedInput.ReadBytes(p,pcm,16*1024*1024);double sum=0,peak=0;for(int i=0;i+1<bytes.Length;i+=2){double sample=BitConverter.ToInt16(bytes,i)/32768.0;sum+=sample*sample;peak=Math.Max(peak,Math.Abs(sample));}if(bytes.Length<32000)throw new IOException("Слишком мало аудиоданных");return Data.Map("samples",bytes.Length/2,"seconds",bytes.Length/32000.0,"rms",Math.Sqrt(sum/(bytes.Length/2)),"peak",peak);}
 }
}